namespace Invoicing;

/// <summary>Resolves the VAT due for a net amount given account and jurisdiction.</summary>
public sealed class VatResolver
{
    public decimal Resolve(Account account, decimal net, string countryCode)
    {
        if (net <= 0m)
            return 0m;

        decimal rate = GetCountryRate(countryCode);
        rate = ApplyAccountRate(rate, account, net);
        rate = ApplyHighValueCap(rate, net);

        return net * rate;
    }

    private static decimal GetCountryRate(string countryCode)
    {
        switch (countryCode)
        {
            case "GB":
                return 0.20m;
            case "DE":
                return 0.19m;
            case "FR":
                return 0.20m;
            case "IE":
                return 0.23m;
            default:
                return 0.0m;
        }
    }

    private static decimal ApplyAccountRate(decimal rate, Account account, decimal net)
    {
        if (account.Kind == AccountKind.Government)
            return 0m;

        if (account.Kind == AccountKind.Business && net > 10000m)
            return rate * 0.5m;

        return rate;
    }

    private static decimal ApplyHighValueCap(decimal rate, decimal net)
    {
        if (rate > 0m && net > 100000m)
            return Math.Min(rate, 0.15m);

        return rate;
    }
}
